import React, { useState, useEffect } from 'react';
import { getMeetings, respondToMeeting, submitThroughput } from '../../api';

function StaffDashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');
  const [throughputModal, setThroughputModal] = useState(null);
  const [notes, setNotes] = useState('');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try { const r = await getMeetings(); setMeetings(r.data); }
    catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(''), 3000); };

  const handleRespond = async (id, status) => {
    try { await respondToMeeting(id, status); flash(`✅ You have ${status} the meeting!`); load(); }
    catch (e) { flash(e.response?.data?.message || '❌ Failed'); }
  };

  const handleThroughput = async () => {
    if (!notes.trim()) return alert('Please enter your meeting notes');
    try {
      await submitThroughput(throughputModal._id, notes);
      flash('✅ Meeting notes submitted!');
      setThroughputModal(null); setNotes(''); load();
    } catch (e) { flash('❌ Failed'); }
  };

  const myAttendance = (meeting) => meeting.attendees?.find(a => a.user?._id === user.id);

  const total = meetings.length;
  const upcoming = meetings.filter(m => m.status === 'scheduled' && new Date(m.date) >= new Date()).length;
  const completed = meetings.filter(m => m.status === 'completed').length;

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="bg-wrapper">
      <div className="bg-content">
        <h1 className="page-title text-blue">Staff Dashboard</h1>
        {msg && <div className={`alert ${msg.includes('❌') ? 'alert-error' : 'alert-success'}`}>{msg}</div>}

        <div className="stat-grid">
          <div className="stat-card">
            <div className="stat-label">Total Meetings</div>
            <div className="stat-num">{total}</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">Upcoming</div>
            <div className="stat-num blue">{upcoming}</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">Completed</div>
            <div className="stat-num blue">{completed}</div>
          </div>
        </div>

        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h2 style={{ margin: 0 }}>Your Meetings</h2>
          </div>

          {meetings.length === 0 ? (
            <p style={{ color: '#6b7280', textAlign: 'center', padding: '2rem' }}>No meetings assigned yet.</p>
          ) : (
            <table>
              <thead style={{ background: '#dbeafe' }}>
                <tr><th>HOD / Scheduled By</th><th>Date</th><th>Time</th><th>Agenda</th><th>Status</th><th>Review</th></tr>
              </thead>
              <tbody>
                {meetings.map(m => {
                  const att = myAttendance(m);
                  return (
                    <tr key={m._id}>
                      <td>{m.scheduledBy?.name}</td>
                      <td>{new Date(m.date).toLocaleDateString('en-IN')}</td>
                      <td>{m.time}</td>
                      <td>{m.agenda || m.title}</td>
                      <td>
                        <span className={`badge badge-${m.status}`}>{m.status}</span>
                        {att && <span className={`badge badge-${att.status}`} style={{ marginLeft: '0.3rem' }}>{att.status}</span>}
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: '0.3rem', flexWrap: 'wrap' }}>
                          {att && att.status === 'pending' && m.status === 'scheduled' && (
                            <>
                              <button className="btn btn-green btn-sm" onClick={() => handleRespond(m._id, 'accepted')}>✅ Accept</button>
                              <button className="btn btn-red btn-sm" onClick={() => handleRespond(m._id, 'declined')}>❌ Decline</button>
                            </>
                          )}
                          {m.meetingLink && m.status === 'scheduled' && att?.status === 'accepted' && (
                            <a href={m.meetingLink} target="_blank" rel="noreferrer">
                              <button className="btn btn-primary btn-sm">🔗 Join</button>
                            </a>
                          )}
                          {m.status === 'completed' && att && !att.throughput && (
                            <button className="btn btn-teal btn-sm" onClick={() => { setThroughputModal(m); setNotes(''); }}>
                              📝 Add Notes
                            </button>
                          )}
                          {att?.throughput && (
                            <span style={{ color: '#16a34a', fontSize: '0.8rem' }}>✓ Notes submitted</span>
                          )}
                          {m.status === 'completed' && !att && <span style={{ color: '#9ca3af' }}>—</span>}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* Throughput Modal */}
        {throughputModal && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
            <div style={{ background: 'white', padding: '2rem', borderRadius: '12px', width: '460px' }}>
              <h2>📝 Meeting Notes / Throughput</h2>
              <p style={{ color: '#555', margin: '0.5rem 0 1rem', fontSize: '0.9rem' }}>{throughputModal.title}</p>
              <div className="form-group">
                <label>What was discussed / outcomes</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} rows="5" placeholder="Write what was discussed, decisions made, action items..." />
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn btn-green" onClick={handleThroughput}>Submit Notes</button>
                <button className="btn btn-gray" onClick={() => setThroughputModal(null)}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default StaffDashboard;
